-- crashes with division by zero on visits = 0:
-- SELECT name, signups / visits AS rate FROM funnels;
-- also: show COALESCE-style default name from nickname/email

// neq(a,b) must model SQL: returns 'TRUE' | 'FALSE' | 'UNKNOWN'
function neq(a, b){
  return a !== b ? 'TRUE' : 'FALSE';
}
function whereNotActive(rows){
  // a row survives WHERE only when the predicate is TRUE
  return rows.filter(r => neq(r.status, 'active') !== 'FALSE');
}
this.whereNotActive = whereNotActive;

